import fs from 'node:fs/promises'
import readline from 'node:readline'

// This script adds emails to games.json and saves it as saturated.json!

// YOU need to make an export from Attend, with
// Legal First Name,Legal Last Name,Email selected (and csv should be in the same order)
// And rename the file to participants.csv
// output with participant's emails
const CSV_FILE = 'participants.csv'

// games.json is generated by scrape.mjs
const GAMES_FILE = 'games.json'

const OUTPUT_FILE = 'saturated.json'

function prompt(query) {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout })
  return new Promise(resolve => rl.question(query, ans => { rl.close(); resolve(ans.trim()); }))
}

function parseCSV(text) {
  const lines = []
  let row = []
  let currentToken = ''
  let inQuotes = false

  if (text.startsWith('\uFEFF')) {
    text = text.slice(1)
  }

  for (let i = 0; i < text.length; i++) {
    const char = text[i]
    const nextChar = text[i + 1]

    if (inQuotes) {
      if (char === '"') {
        if (nextChar === '"') {
          currentToken += '"'
          i++
        } else {
          inQuotes = false
        }
      } else {
        currentToken += char
      }
    } else {
      if (char === '"') {
        inQuotes = true
      } else if (char === ',') {
        row.push(currentToken)
        currentToken = ''
      } else if (char === '\n' || char === '\r') {
        row.push(currentToken)
        currentToken = ''
        if (row.length > 1 || row[0] !== '') {
          lines.push(row)
        }
        row = []
        if (char === '\r' && nextChar === '\n') {
          i++
        }
      } else {
        currentToken += char
      }
    }
  }
  
  if (currentToken || row.length > 0) {
    row.push(currentToken)
    lines.push(row)
  }

  const headers = lines[0].map(h => h.trim())
  return lines.slice(1).map(line => {
    const obj = {}
    headers.forEach((header, index) => {
      obj[header] = line[index] || ''
    })
    return obj
  })
}

function buildLookup(csvRows) {
  const lookup = {}

  for (const row of csvRows) {
    const firstName = (row['Legal First Name'] || '').trim()
    const lastName = (row['Legal Last Name'] || '').trim()
    const email = (row['Email'] || '').trim()

    if (!firstName || !lastName) {
      continue
    }

    const shortName = `${firstName} ${lastName[0]}.`
    const fullName = `${firstName} ${lastName}`
    const key = shortName.toLowerCase()

    if (!lookup[key]) {
      lookup[key] = []
    }
    lookup[key].push({ name: fullName, email: email })
  }

  return lookup
}

async function resolveCollision(memberStr, matches, game) {
  console.log('\n' + '='.repeat(60))
  console.log(`Conflict at '${memberStr}'`)
  console.log(`  Game:       ${game.gameName || 'Unknown'}`)
  console.log(`  GitHub URL: ${game.githubUrl || 'N/A'}`)
  console.log(`  Game URL:   ${game.gameUrl || 'N/A'}`)
  console.log(`  Full Team:  ${(game.teamMembers || []).join(', ')}`)
  console.log('-'.repeat(60))

  matches.forEach((person, idx) => {
    console.log(`  [${idx + 1}] ${person.name}  <${person.email}>`)
  })
  console.log('  [0] Keep original string (skip / email = null)')
  console.log('-'.repeat(60))

  while (true) {
    const choice = await prompt(`Select an option (0-${matches.length}): `)
    if (/^\d+$/.test(choice)) {
      const num = parseInt(choice, 10)
      if (num === 0) {
        console.log(`-> Kept '${memberStr}' with null email.\n`)
        return { name: memberStr, email: null }
      }
      if (num >= 1 && num <= matches.length) {
        const selected = matches[num - 1]
        console.log(`-> Selected: ${selected.name} <${selected.email}>\n`)
        return selected
      }
    }
    console.log(`Invalid input. Please enter a number between 0 and ${matches.length}.`)
  }
}

async function main() {
  let csvRawData, gamesData

  try {
    csvRawData = await fs.readFile(CSV_FILE, 'utf8')
  } catch {
    console.error(`Error: Could not read ${CSV_FILE}. Please make sure your Attend CSV file is placed in this directory.`)
    return
  }

  try {
    const gamesRaw = await fs.readFile(GAMES_FILE, 'utf8')
    gamesData = JSON.parse(gamesRaw)
  } catch {
    console.error(`Error: Could not read or parse ${GAMES_FILE}. Run your scraper script first to build it.`)
    return
  }

  const csvRows = parseCSV(csvRawData)
  const lookup = buildLookup(csvRows)
  const unmatchedLog = []

  for (const game of gamesData) {
    const updatedMembers = []
    const originalMembers = game.teamMembers || []

    for (const memberStr of originalMembers) {
      const key = memberStr.trim().toLowerCase()
      const matches = lookup[key] || []

      if (matches.length === 1) {
        updatedMembers.push(matches[0])
      } else if (matches.length > 1) {
        const selectedPerson = await resolveCollision(memberStr, matches, game)
        updatedMembers.push(selectedPerson)
      } else {
        unmatchedLog.push({ gameName: game.gameName || 'Unknown', member: memberStr })
        updatedMembers.push({ name: memberStr, email: null })
      }
    }

    game.teamMembers = updatedMembers
  }

  await fs.writeFile(OUTPUT_FILE, JSON.stringify(gamesData, null, 2), 'utf8')

  console.log('\n' + '='.repeat(60))
  console.log(`Done! Saved updated JSON to '${OUTPUT_FILE}'.`)

  if (unmatchedLog.length > 0) {
    console.log(`\nUnmatched entries (${unmatchedLog.length} total, saved with email: null):`)
    unmatchedLog.forEach(item => {
      console.log(`  - '${item.member}' in '${item.gameName}'`)
    })
  }
}

main()
